 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    # Each nonzero input cell becomes a 3x3 tile whose pattern is the
    # complement of the input's nonzero-cell mask.
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                for tr in range(h):
                    for tc in range(w):
                        if grid[tr][tc] == 0:
                            out[3 * r + tr][3 * c + tc] = value
    return out
